import React from 'react';
import { useNavigate } from 'react-router-dom';


function Login() {

    const navigate = useNavigate();

  return (
    <div className="w-full h-screen flex items-center justify-center" style={{ backgroundColor: '#368CE7' }}>
      <div className="bg-white p-8 rounded-lg shadow-md w-full max-w-sm">
        <h2 className="text-2xl font-semibold text-center text-blue-600 mb-4">
          Welcome!
        </h2>

        {/* Email Input */}
        <div className="mb-4">
          <input
            type="email"
            className="w-full p-2 bg-white bg-opacity-20 rounded-md text-white placeholder-white focus:ring-blue-500"
            placeholder="Email"
          />
        </div>

        {/* Password Input */}
        <div className="mb-6">
          <input
            type="password"
            className="w-full p-2 bg-white bg-opacity-20 rounded-md text-white placeholder-white focus:ring-blue-500"
            placeholder="Password"
          />
        </div>

        {/* Buttons */}
        <button className="w-full bg-blue-600 text-white py-2 rounded-md hover:bg-blue-700 transition">
          Login
        </button>

        <div className="text-center my-4 text-gray-500">or</div>

        <button className="w-full bg-gray-300 text-gray-700 py-2 rounded-md hover:bg-gray-400 transition" onClick={() => navigate('/') }>
          Continue as Guest
        </button>
      </div>
    </div>
  );
}

export default Login;
